const fs = require("fs");
const path = require("path");
const { execFileSync, execSync } = require("child_process");

const root = process.cwd();
const P = (...parts) => path.join(root, ...parts);
function fail(message) { console.error("\nERROR: " + message); process.exit(1); }

let branch = "";
try {
  branch = execFileSync("git", ["branch", "--show-current"], { cwd: root, encoding: "utf8" }).trim();
} catch {
  fail("تعذر قراءة فرع Git.");
}
if (branch !== "v2-dev") fail("شغّل الملف داخل فرع v2-dev فقط. الفرع الحالي: " + branch);

const files = {
  teacher: P("src", "TeacherPlatform.tsx"),
  css: P("src", "platform.css"),
  dashboard: P("src", "TeacherDashboard.tsx"),
  analytics: P("api", "src", "functions", "teacher-analytics.js")
};

for (const file of [files.teacher, files.css]) {
  if (!fs.existsSync(file)) fail("الملف غير موجود: " + file);
}

let teacher = fs.readFileSync(files.teacher, "utf8");
if (!teacher.includes("ExamBank 2.0H") && !teacher.includes("ExamBank 2.0I")) {
  fail("Phase 2.0H غير موجودة في TeacherPlatform.tsx. شغّل Phase H وإصلاحها أولًا.");
}

const suffix = ".bak-phase2i-dashboard";
for (const file of [files.teacher, files.css, files.dashboard, files.analytics]) {
  if (fs.existsSync(file)) {
    const backup = file + suffix;
    if (!fs.existsSync(backup)) fs.copyFileSync(file, backup);
  }
}

const analyticsBackend = "const { app } = require(\"@azure/functions\");\nconst { requireBuilderAuth } = require(\"../lib/builder-auth\");\nconst { getContainer, listJson } = require(\"../lib/platform-storage\");\n\nconst CLASS_PREFIX = \"platform/classes/\";\nconst USER_PREFIX = \"platform/users/\";\nconst ASSIGNMENT_PREFIX = \"platform/assignments/\";\nconst SUBMISSION_PREFIX = \"platform/submissions/\";\n\nfunction number(value) {\n  const n = Number(value);\n  return Number.isFinite(n) ? n : 0;\n}\n\nfunction round(value, digits = 1) {\n  const power = 10 ** digits;\n  return Math.round((number(value) + Number.EPSILON) * power) / power;\n}\n\nfunction timestamp(value) {\n  if (!value) return 0;\n  const t = new Date(value).getTime();\n  return Number.isFinite(t) ? t : 0;\n}\n\nfunction inRange(value, fromMs, toMs) {\n  if (!fromMs && !toMs) return true;\n  const t = timestamp(value);\n  if (!t) return false;\n  if (fromMs && t < fromMs) return false;\n  if (toMs && t > toMs) return false;\n  return true;\n}\n\nfunction assignmentDate(assignment) {\n  return assignment.dueAt || assignment.openAt || assignment.createdAt || assignment.updatedAt || \"\";\n}\n\nfunction latestAttempt(submission) {\n  const attempts = Array.isArray(submission?.attempts) ? submission.attempts : [];\n  if (!attempts.length) return null;\n  return [...attempts].sort((a, b) => timestamp(a.submittedAt) - timestamp(b.submittedAt)).at(-1) || null;\n}\n\nfunction average(values) {\n  const nums = values.map(number).filter(Number.isFinite);\n  return nums.length ? round(nums.reduce((sum, value) => sum + value, 0) / nums.length, 1) : null;\n}\n\nfunction trendDelta(points) {\n  const values = points.map(point => number(point.percentage));\n  if (values.length < 2) return 0;\n  if (values.length >= 4) {\n    const previous = average(values.slice(-4, -2)) ?? 0;\n    const recent = average(values.slice(-2)) ?? 0;\n    return round(recent - previous, 1);\n  }\n  return round(values.at(-1) - values[0], 1);\n}\n\nfunction trendLabel(delta) {\n  if (delta >= 5) return \"improving\";\n  if (delta <= -5) return \"declining\";\n  return \"stable\";\n}\n\nfunction studentName(student) {\n  return String(student?.displayName || [student?.firstName, student?.familyName].filter(Boolean).join(\" \") || \"طالب\");\n}\n\nfunction qid(question, index) {\n  return String(question?.examQuestionId || question?.id || question?.number || index + 1);\n}\n\nfunction classAggregate(classId, assignments, students, submissionMap) {\n  const classStudents = students.filter(student => String(student.classId || \"\") === classId && student.active !== false && student.archived !== true);\n  const classAssignments = assignments.filter(assignment => String(assignment.classId || \"\") === classId);\n  let submitted = 0;\n  let pendingReview = 0;\n  const percentages = [];\n\n  for (const assignment of classAssignments) {\n    for (const student of classStudents) {\n      const submission = submissionMap.get(String(assignment.assignmentId) + \"|\" + String(student.userId));\n      const attempt = latestAttempt(submission);\n      if (!attempt) continue;\n      submitted += 1;\n      percentages.push(number(attempt.percentage));\n      if (attempt.finalized === false) pendingReview += 1;\n    }\n  }\n\n  const expected = classStudents.length * classAssignments.length;\n  return {\n    students: classStudents.length,\n    assignments: classAssignments.length,\n    expected,\n    submitted,\n    missing: Math.max(0, expected - submitted),\n    pendingReview,\n    completionRate: expected ? round(submitted / expected * 100, 1) : 0,\n    average: average(percentages)\n  };\n}\n\napp.http(\"teacherAnalytics\", {\n  methods: [\"GET\"],\n  authLevel: \"anonymous\",\n  route: \"teacher-analytics\",\n  handler: async request => {\n    try {\n      const auth = requireBuilderAuth(request);\n      if (!auth.ok) return auth.response;\n\n      const url = new URL(request.url);\n      const requestedClassId = String(url.searchParams.get(\"classId\") || \"\").trim();\n      const fromMs = timestamp(url.searchParams.get(\"from\"));\n      const toMs = timestamp(url.searchParams.get(\"to\"));\n\n      const container = getContainer();\n      const [classesRaw, usersRaw, assignmentsRaw, submissionsRaw] = await Promise.all([\n        listJson(container, CLASS_PREFIX),\n        listJson(container, USER_PREFIX),\n        listJson(container, ASSIGNMENT_PREFIX),\n        listJson(container, SUBMISSION_PREFIX)\n      ]);\n\n      const classes = classesRaw\n        .filter(item => item?.classId)\n        .map(item => ({\n          classId: String(item.classId),\n          name: String(item.name || \"\"),\n          grade: String(item.grade || \"\"),\n          schoolYear: String(item.schoolYear || \"\"),\n          active: item.active !== false\n        }))\n        .sort((a, b) => a.name.localeCompare(b.name, \"ar\", { numeric: true }));\n\n      const classMap = new Map(classes.map(item => [item.classId, item]));\n      const students = usersRaw.filter(item => item?.role === \"student\");\n      const activeStudents = students.filter(item => item.active !== false && item.archived !== true);\n      const publishedAll = assignmentsRaw.filter(item => item?.assignmentId && item.status === \"published\");\n      const scopedByDate = publishedAll.filter(item => inRange(assignmentDate(item), fromMs, toMs));\n      const scopedAssignments = scopedByDate.filter(item => !requestedClassId || String(item.classId || \"\") === requestedClassId);\n      const scopedStudents = activeStudents.filter(item => !requestedClassId || String(item.classId || \"\") === requestedClassId);\n\n      const submissionMap = new Map();\n      for (const submission of submissionsRaw) {\n        const assignmentId = String(submission?.assignmentId || \"\");\n        const studentId = String(submission?.studentId || \"\");\n        if (assignmentId && studentId) submissionMap.set(assignmentId + \"|\" + studentId, submission);\n      }\n\n      const records = [];\n      for (const assignment of scopedAssignments) {\n        const classStudents = scopedStudents.filter(student => String(student.classId || \"\") === String(assignment.classId || \"\"));\n        for (const student of classStudents) {\n          const submission = submissionMap.get(String(assignment.assignmentId) + \"|\" + String(student.userId));\n          const attempt = latestAttempt(submission);\n          records.push({ assignment, student, submission, attempt });\n        }\n      }\n\n      const submittedRecords = records.filter(record => record.attempt);\n      const percentages = submittedRecords.map(record => number(record.attempt.percentage));\n      const expected = records.length;\n      const submitted = submittedRecords.length;\n      const missing = Math.max(0, expected - submitted);\n      const pendingReview = submittedRecords.filter(record => record.attempt.finalized === false).length;\n      const late = submittedRecords.filter(record => {\n        const due = timestamp(record.assignment.dueAt);\n        return due && timestamp(record.attempt.submittedAt) > due;\n      }).length;\n\n      const studentMap = new Map();\n      for (const student of scopedStudents) {\n        studentMap.set(String(student.userId), {\n          userId: String(student.userId),\n          displayName: studentName(student),\n          identityNumber: String(student.identityNumber || student.code || \"\"),\n          classId: String(student.classId || \"\"),\n          className: classMap.get(String(student.classId || \"\"))?.name || \"\",\n          active: student.active !== false,\n          lastLoginAt: String(student.lastLoginAt || \"\"),\n          assigned: 0,\n          completed: 0,\n          missing: 0,\n          scores: [],\n          points: []\n        });\n      }\n\n      for (const record of records) {\n        const item = studentMap.get(String(record.student.userId));\n        if (!item) continue;\n        item.assigned += 1;\n        if (record.attempt) {\n          item.completed += 1;\n          item.scores.push(number(record.attempt.percentage));\n          item.points.push({\n            assignmentId: String(record.assignment.assignmentId),\n            title: String(record.assignment.title || \"\"),\n            date: assignmentDate(record.assignment),\n            percentage: number(record.attempt.percentage)\n          });\n        } else {\n          item.missing += 1;\n        }\n      }\n\n      const studentSummaries = [...studentMap.values()].map(item => {\n        item.points.sort((a, b) => timestamp(a.date) - timestamp(b.date));\n        const avg = average(item.scores);\n        const delta = trendDelta(item.points);\n        const reasons = [];\n        if (avg !== null && avg < 60) reasons.push(\"معدل منخفض\");\n        if (item.missing >= 2) reasons.push(item.missing + \" واجبات غير مسلّمة\");\n        if (!item.lastLoginAt) reasons.push(\"لم يسجل الدخول بعد\");\n        if (delta <= -8) reasons.push(\"تراجع ملحوظ في الأداء\");\n        const severity = (avg !== null && avg < 50) || item.missing >= 3 || delta <= -15 ? \"high\" : reasons.length ? \"medium\" : \"low\";\n        return {\n          userId: item.userId,\n          displayName: item.displayName,\n          identityNumber: item.identityNumber,\n          classId: item.classId,\n          className: item.className,\n          average: avg,\n          assigned: item.assigned,\n          completed: item.completed,\n          missing: item.missing,\n          completionRate: item.assigned ? round(item.completed / item.assigned * 100, 1) : 0,\n          trendDelta: delta,\n          trend: trendLabel(delta),\n          lastLoginAt: item.lastLoginAt,\n          needsFollowUp: reasons.length > 0,\n          severity,\n          reasons\n        };\n      });\n\n      const followUp = studentSummaries\n        .filter(item => item.needsFollowUp)\n        .sort((a, b) => {\n          const severity = { high: 2, medium: 1, low: 0 };\n          return (severity[b.severity] - severity[a.severity]) || (b.missing - a.missing) || ((a.average ?? 101) - (b.average ?? 101));\n        })\n        .slice(0, 20);\n\n      const topImprovers = studentSummaries\n        .filter(item => item.completed >= 2 && item.trendDelta > 0)\n        .sort((a, b) => b.trendDelta - a.trendDelta)\n        .slice(0, 8);\n\n      const classComparison = classes\n        .filter(item => item.active)\n        .map(classroom => ({\n          classId: classroom.classId,\n          name: classroom.name,\n          grade: classroom.grade,\n          ...classAggregate(classroom.classId, scopedByDate, activeStudents, submissionMap)\n        }))\n        .filter(item => item.students > 0 || item.assignments > 0)\n        .sort((a, b) => (b.average ?? -1) - (a.average ?? -1));\n\n      const assignmentTrend = scopedAssignments\n        .map(assignment => {\n          const assignmentRecords = records.filter(record => String(record.assignment.assignmentId) === String(assignment.assignmentId));\n          const assignmentSubmitted = assignmentRecords.filter(record => record.attempt);\n          const assignmentPercentages = assignmentSubmitted.map(record => number(record.attempt.percentage));\n          return {\n            assignmentId: String(assignment.assignmentId),\n            classId: String(assignment.classId || \"\"),\n            className: String(assignment.className || classMap.get(String(assignment.classId || \"\"))?.name || \"\"),\n            title: String(assignment.title || \"واجب\"),\n            dueAt: String(assignment.dueAt || \"\"),\n            date: assignmentDate(assignment),\n            students: assignmentRecords.length,\n            submitted: assignmentSubmitted.length,\n            missing: Math.max(0, assignmentRecords.length - assignmentSubmitted.length),\n            pendingReview: assignmentSubmitted.filter(record => record.attempt.finalized === false).length,\n            completionRate: assignmentRecords.length ? round(assignmentSubmitted.length / assignmentRecords.length * 100, 1) : 0,\n            average: average(assignmentPercentages),\n            highest: assignmentPercentages.length ? round(Math.max(...assignmentPercentages), 1) : null,\n            lowest: assignmentPercentages.length ? round(Math.min(...assignmentPercentages), 1) : null\n          };\n        })\n        .sort((a, b) => timestamp(a.date) - timestamp(b.date));\n\n      const trendAverages = assignmentTrend.filter(item => item.average !== null).map(item => number(item.average));\n      let performanceChange = 0;\n      if (trendAverages.length >= 4) {\n        performanceChange = round((average(trendAverages.slice(-2)) ?? 0) - (average(trendAverages.slice(-4, -2)) ?? 0), 1);\n      } else if (trendAverages.length >= 2) {\n        performanceChange = round(trendAverages.at(-1) - trendAverages.at(-2), 1);\n      }\n\n      const gradeDistribution = [\n        { label: \"90–100\", min: 90, max: 101 },\n        { label: \"80–89\", min: 80, max: 90 },\n        { label: \"70–79\", min: 70, max: 80 },\n        { label: \"60–69\", min: 60, max: 70 },\n        { label: \"أقل من 60\", min: -1, max: 60 }\n      ].map(bin => ({\n        label: bin.label,\n        count: percentages.filter(value => value >= bin.min && value < bin.max).length\n      }));\n\n      const topicMap = new Map();\n      for (const record of submittedRecords) {\n        const questions = Array.isArray(record.assignment?.examSnapshot?.questions) ? record.assignment.examSnapshot.questions : [];\n        const questionMap = new Map(questions.map((question, index) => [qid(question, index), question]));\n        const grades = Array.isArray(record.attempt?.questionGrades) ? record.attempt.questionGrades : [];\n        for (const grade of grades) {\n          if (grade?.manualReview === true && grade?.reviewed !== true) continue;\n          const question = questionMap.get(String(grade?.questionId || \"\"));\n          if (!question) continue;\n          const topic = String(question.topic || \"غير مصنف\").trim() || \"غير مصنف\";\n          const maxMarks = number(grade.maxMarks);\n          if (maxMarks <= 0) continue;\n          const current = topicMap.get(topic) || { topic, score: 0, maxMarks: 0, gradedQuestions: 0 };\n          current.score += number(grade.score);\n          current.maxMarks += maxMarks;\n          current.gradedQuestions += 1;\n          topicMap.set(topic, current);\n        }\n      }\n\n      const topicAnalytics = [...topicMap.values()]\n        .map(item => ({\n          topic: item.topic,\n          average: item.maxMarks ? round(item.score / item.maxMarks * 100, 1) : null,\n          gradedQuestions: item.gradedQuestions\n        }))\n        .sort((a, b) => (a.average ?? 101) - (b.average ?? 101));\n\n      const insights = [];\n      if (performanceChange >= 3) {\n        insights.push({ tone: \"success\", title: \"اتجاه الأداء إيجابي\", text: \"متوسط الأداء ارتفع \" + Math.abs(performanceChange) + \"% مقارنة بالفترة السابقة من الواجبات.\" });\n      } else if (performanceChange <= -3) {\n        insights.push({ tone: \"warning\", title: \"يوجد تراجع في الأداء\", text: \"متوسط الأداء انخفض \" + Math.abs(performanceChange) + \"%؛ يفضّل مراجعة آخر الواجبات والموضوعات الأضعف.\" });\n      } else if (trendAverages.length >= 2) {\n        insights.push({ tone: \"info\", title: \"الأداء مستقر\", text: \"لا يوجد تغير كبير في متوسط النتائج بين آخر الواجبات.\" });\n      }\n\n      const weakestTopic = topicAnalytics.find(item => item.average !== null && item.average < 70);\n      if (weakestTopic) {\n        insights.push({ tone: \"warning\", title: \"موضوع يحتاج مراجعة\", text: \"متوسط الأداء في \" + weakestTopic.topic + \" هو \" + weakestTopic.average + \"%، وهو من أضعف الموضوعات حاليًا.\" });\n      }\n\n      const strongestTopic = [...topicAnalytics].reverse().find(item => item.average !== null && item.average >= 85);\n      if (strongestTopic) {\n        insights.push({ tone: \"success\", title: \"نقطة قوة\", text: \"الأداء في \" + strongestTopic.topic + \" قوي بمتوسط \" + strongestTopic.average + \"% .\" });\n      }\n\n      if (followUp.length) {\n        insights.push({ tone: \"warning\", title: \"طلاب يحتاجون متابعة\", text: followUp.length + \" طالبًا لديهم مؤشر متابعة مثل انخفاض المعدل أو واجبات ناقصة أو تراجع في الأداء.\" });\n      }\n      if (missing) {\n        insights.push({ tone: \"info\", title: \"تسليمات ناقصة\", text: \"يوجد \" + missing + \" حالة عدم تسليم ضمن النطاق الحالي.\" });\n      }\n      if (pendingReview) {\n        insights.push({ tone: \"info\", title: \"مراجعة يدوية مطلوبة\", text: \"هناك \" + pendingReview + \" تسليمًا يحتوي أسئلة تحتاج مراجعة أو تصحيحًا يدويًا.\" });\n      }\n\n      const neverLogged = scopedStudents.filter(student => !student.lastLoginAt).length;\n      if (neverLogged) {\n        insights.push({ tone: \"warning\", title: \"طلاب لم يدخلوا بعد\", text: neverLogged + \" طالبًا فعّالًا لم يسجلوا الدخول إلى المنصة بعد.\" });\n      }\n\n      if (!insights.length) {\n        insights.push({ tone: \"success\", title: \"الوضع مستقر\", text: \"لا توجد مؤشرات تنبيه بارزة في البيانات الحالية.\" });\n      }\n\n      return {\n        status: 200,\n        jsonBody: {\n          ok: true,\n          generatedAt: new Date().toISOString(),\n          scope: {\n            classId: requestedClassId,\n            className: classMap.get(requestedClassId)?.name || \"كل الصفوف\",\n            from: fromMs ? new Date(fromMs).toISOString() : \"\",\n            to: toMs ? new Date(toMs).toISOString() : \"\"\n          },\n          classes: classes.map(classroom => ({\n            ...classroom,\n            studentCount: activeStudents.filter(student => String(student.classId || \"\") === classroom.classId).length\n          })),\n          kpis: {\n            activeClasses: classes.filter(item => item.active).length,\n            activeStudents: scopedStudents.length,\n            publishedAssignments: scopedAssignments.length,\n            submissions: submitted,\n            expectedSubmissions: expected,\n            missingSubmissions: missing,\n            pendingReview,\n            lateSubmissions: late,\n            completionRate: expected ? round(submitted / expected * 100, 1) : 0,\n            average: average(percentages),\n            highest: percentages.length ? round(Math.max(...percentages), 1) : null,\n            lowest: percentages.length ? round(Math.min(...percentages), 1) : null,\n            performanceChange,\n            followUpStudents: followUp.length,\n            neverLogged\n          },\n          submissionStatus: {\n            submitted,\n            missing,\n            pendingReview,\n            late\n          },\n          gradeDistribution,\n          assignmentTrend: assignmentTrend.slice(-14),\n          classComparison,\n          topicAnalytics: topicAnalytics.slice(0, 14),\n          followUp,\n          topImprovers,\n          insights: insights.slice(0, 7)\n        }\n      };\n    } catch (error) {\n      return {\n        status: 500,\n        jsonBody: {\n          ok: false,\n          error: error instanceof Error ? error.message : \"Teacher analytics failed.\"\n        }\n      };\n    }\n  }\n});\n";
const dashboardFrontend = "import {useEffect,useMemo,useState} from \"react\";\n\ntype DashboardProps={token:string};\ntype ClassItem={classId:string;name:string;grade:string;schoolYear:string;active:boolean;studentCount:number};\ntype AssignmentTrend={assignmentId:string;classId:string;className:string;title:string;dueAt:string;date:string;students:number;submitted:number;missing:number;pendingReview:number;completionRate:number;average:number|null;highest:number|null;lowest:number|null};\ntype ClassComparison={classId:string;name:string;grade:string;students:number;assignments:number;expected:number;submitted:number;missing:number;pendingReview:number;completionRate:number;average:number|null};\ntype TopicAnalytics={topic:string;average:number|null;gradedQuestions:number};\ntype FollowUp={userId:string;displayName:string;identityNumber:string;classId:string;className:string;average:number|null;assigned:number;completed:number;missing:number;completionRate:number;trendDelta:number;trend:\"improving\"|\"declining\"|\"stable\";lastLoginAt:string;severity:\"high\"|\"medium\"|\"low\";reasons:string[]};\ntype Insight={tone:\"success\"|\"warning\"|\"info\";title:string;text:string};\ntype Analytics={\n ok:true;generatedAt:string;\n scope:{classId:string;className:string;from:string;to:string};\n classes:ClassItem[];\n kpis:{activeClasses:number;activeStudents:number;publishedAssignments:number;submissions:number;expectedSubmissions:number;missingSubmissions:number;pendingReview:number;lateSubmissions:number;completionRate:number;average:number|null;highest:number|null;lowest:number|null;performanceChange:number;followUpStudents:number;neverLogged:number};\n submissionStatus:{submitted:number;missing:number;pendingReview:number;late:number};\n gradeDistribution:Array<{label:string;count:number}>;\n assignmentTrend:AssignmentTrend[];\n classComparison:ClassComparison[];\n topicAnalytics:TopicAnalytics[];\n followUp:FollowUp[];\n topImprovers:FollowUp[];\n insights:Insight[];\n};\ntype ApiError={ok?:boolean;error?:string};\ntype StudentProfile={\n student:{userId:string;displayName:string;identityNumber:string;firstName:string;familyName:string;classId:string;active:boolean;archived:boolean;createdAt:string;lastLoginAt:string};\n classroom:{classId:string;name:string;grade:string;schoolYear:string}|null;\n stats:{assigned:number;completed:number;pending:number;average:number|null;lastLoginAt:string};\n assignments:Array<{assignmentId:string;title:string;status:string;dueAt:string;totalMarks:number;attemptsUsed:number;latestScore:number|null;latestPercentage:number|null;submittedAt:string;finalized:boolean}>;\n};\ntype AssignmentResults={\n assignment:{assignmentId:string;title:string;maxAttempts:number;totalMarks:number};\n stats:{students:number;submitted:number;pendingReview:number;average:number|null;highest:number|null;lowest:number|null};\n students:Array<{studentId:string;studentName:string;studentCode:string;attemptsUsed:number;allowedAttempts:number;attempts:Array<{attemptNumber:number;score:number;totalMarks:number;percentage:number;submittedAt:string;finalized:boolean}>;latestResult:{attemptNumber:number;score:number;totalMarks:number;percentage:number;submittedAt:string;finalized:boolean}|null}>;\n};\ntype AttemptReview={\n assignment:{assignmentId:string;title:string;totalMarks:number};\n student:{studentId:string;studentName:string;studentCode:string};\n attempt:{attemptNumber:number;submittedAt:string;score:number;totalMarks:number;percentage:number;manualReviewMarks:number;finalized:boolean;teacherFeedback:string};\n attempts:Array<{attemptNumber:number;submittedAt:string;score:number;totalMarks:number;percentage:number;manualReviewMarks:number;finalized:boolean}>;\n questions:Array<{questionId:string;questionNumber:number;text:string;marks:number;type:string;autoGrade:{score:number;maxMarks:number;correct:boolean;manualReview:boolean;reviewed?:boolean}|null;manualScore:number|null;teacherComment:string}>;\n};\ntype RangeKey=\"all\"|\"30\"|\"90\"|\"365\";\n\nconst fmtDate=(value:string)=>value?new Date(value).toLocaleString(\"ar\",{dateStyle:\"medium\",timeStyle:\"short\"}):\"—\";\nconst fmtPct=(value:number|null)=>value===null?\"—\":value.toFixed(1).replace(/\\.0$/,\"\")+\"%\";\nconst clampPct=(value:number|null)=>Math.max(0,Math.min(100,Number(value??0)));\nconst maskIdentity=(value:string)=>value?\"•••••\"+value.slice(-4):\"—\";\nconst trendText=(delta:number)=>delta>=5?\"يتحسن\":delta<=-5?\"يتراجع\":\"مستقر\";\nconst trendIcon=(delta:number)=>delta>=5?\"↑\":delta<=-5?\"↓\":\"→\";\nconst csvCell=(value:unknown)=>`\"${String(value??\"\").replace(/\"/g,'\"\"')}\"`;\n\nfunction LineChart({items}:{items:AssignmentTrend[]}){\n const points=items.filter(item=>item.average!==null);\n if(points.length<2)return <div className=\"analytics-empty-chart\">تظهر حركة الأداء بعد توفر نتيجتين على الأقل.</div>;\n const width=760,height=250,padX=42,padTop=24,padBottom=48;\n const usableW=width-padX*2,usableH=height-padTop-padBottom;\n const coords=points.map((item,index)=>{\n  const x=padX+(index/(points.length-1))*usableW;\n  const y=padTop+(100-clampPct(item.average))/100*usableH;\n  return {x,y,item};\n });\n const path=coords.map((point,index)=>(index?\"L\":\"M\")+point.x.toFixed(1)+\" \"+point.y.toFixed(1)).join(\" \");\n return <div className=\"analytics-line-wrap\"><svg viewBox={`0 0 ${width} ${height}`} role=\"img\" aria-label=\"تطور متوسط العلامات\">\n  {[0,25,50,75,100].map(value=>{const y=padTop+(100-value)/100*usableH;return <g key={value}><line className=\"analytics-grid-line\" x1={padX} x2={width-padX} y1={y} y2={y}/><text className=\"analytics-axis-text\" x={8} y={y+4}>{value}%</text></g>})}\n  <path className=\"analytics-trend-area\" d={`${path} L ${coords.at(-1)?.x} ${padTop+usableH} L ${coords[0].x} ${padTop+usableH} Z`}/>\n  <path className=\"analytics-trend-line\" d={path}/>\n  {coords.map(({x,y,item},index)=><g key={item.assignmentId}>\n   <circle className=\"analytics-trend-dot\" cx={x} cy={y} r={4}/>\n   <text className=\"analytics-point-value\" x={x} y={y-10} textAnchor=\"middle\">{fmtPct(item.average)}</text>\n   {(points.length<=8||index===0||index===points.length-1||index%2===0)&&<text className=\"analytics-axis-label\" x={x} y={height-18} textAnchor=\"middle\">{item.title.length>12?item.title.slice(0,12)+\"…\":item.title}</text>}\n  </g>)}\n </svg></div>;\n}\n\nfunction DonutChart({submitted,missing,pendingReview}:{submitted:number;missing:number;pendingReview:number}){\n const total=Math.max(1,submitted+missing),circumference=263.89;\n const submittedPct=submitted/total;\n const missingPct=missing/total;\n return <div className=\"analytics-donut-layout\">\n  <svg className=\"analytics-donut\" viewBox=\"0 0 120 120\" role=\"img\" aria-label=\"حالة التسليم\">\n   <circle className=\"donut-track\" cx=\"60\" cy=\"60\" r=\"42\"/>\n   <circle className=\"donut-submitted\" cx=\"60\" cy=\"60\" r=\"42\" strokeDasharray={`${submittedPct*circumference} ${circumference}`} strokeDashoffset=\"0\"/>\n   <circle className=\"donut-missing\" cx=\"60\" cy=\"60\" r=\"42\" strokeDasharray={`${missingPct*circumference} ${circumference}`} strokeDashoffset={-submittedPct*circumference}/>\n   <text className=\"donut-main\" x=\"60\" y=\"57\" textAnchor=\"middle\">{Math.round(submittedPct*100)}%</text>\n   <text className=\"donut-sub\" x=\"60\" y=\"72\" textAnchor=\"middle\">تسليم</text>\n  </svg>\n  <div className=\"analytics-legend\"><span><i className=\"legend-dot submitted\"/>تم التسليم <b>{submitted}</b></span><span><i className=\"legend-dot missing\"/>لم يُسلّم <b>{missing}</b></span><span><i className=\"legend-dot review\"/>تحتاج مراجعة <b>{pendingReview}</b></span></div>\n </div>;\n}\n\nfunction TeacherDashboard({token}:DashboardProps){\n const [data,setData]=useState<Analytics|null>(null);\n const [classId,setClassId]=useState(\"\");\n const [range,setRange]=useState<RangeKey>(\"all\");\n const [loading,setLoading]=useState(false);\n const [error,setError]=useState(\"\");\n const [assignmentResults,setAssignmentResults]=useState<AssignmentResults|null>(null);\n const [assignmentBusy,setAssignmentBusy]=useState(false);\n const [profile,setProfile]=useState<StudentProfile|null>(null);\n const [profileBusy,setProfileBusy]=useState(false);\n const [review,setReview]=useState<AttemptReview|null>(null);\n const [reviewBusy,setReviewBusy]=useState(false);\n\n async function teacherApi<T>(url:string):Promise<T>{\n  const response=await fetch(url,{headers:{\"x-builder-token\":token,\"Authorization\":\"Bearer \"+token}});\n  const result=await response.json() as T&ApiError;\n  if(!response.ok)throw new Error(result.error||\"تعذر تحميل البيانات.\");\n  return result;\n }\n\n function queryString(){\n  const params=new URLSearchParams();\n  if(classId)params.set(\"classId\",classId);\n  if(range!==\"all\"){\n   const days=Number(range);\n   const from=new Date(Date.now()-days*24*60*60*1000);\n   params.set(\"from\",from.toISOString());\n   params.set(\"to\",new Date().toISOString());\n  }\n  return params.toString()?\"?\"+params.toString():\"\";\n }\n\n async function loadDashboard(){\n  setLoading(true);setError(\"\");\n  try{\n   const result=await teacherApi<Analytics>(\"/api/teacher-analytics\"+queryString());\n   setData(result);\n   setAssignmentResults(null);setReview(null);setProfile(null);\n  }catch(e){setError(e instanceof Error?e.message:\"تعذر تحميل لوحة المتابعة.\");}\n  finally{setLoading(false)}\n }\n\n useEffect(()=>{void loadDashboard()},[classId,range]);\n\n const maxDistribution=useMemo(()=>Math.max(1,...(data?.gradeDistribution.map(item=>item.count)||[1])),[data]);\n const maxClassAverage=useMemo(()=>Math.max(1,...(data?.classComparison.map(item=>Number(item.average||0))||[1])),[data]);\n\n async function openAssignment(item:AssignmentTrend){\n  setAssignmentBusy(true);setError(\"\");setReview(null);\n  try{\n   const result=await teacherApi<{ok:true}&AssignmentResults>(\"/api/assignment-results?assignmentId=\"+encodeURIComponent(item.assignmentId));\n   setAssignmentResults(result);\n  }catch(e){setError(e instanceof Error?e.message:\"تعذر فتح تفاصيل الواجب.\");}\n  finally{setAssignmentBusy(false)}\n }\n\n async function openProfile(userId:string){\n  setProfileBusy(true);setError(\"\");\n  try{\n   const result=await teacherApi<{ok:true;profile:StudentProfile}>(\"/api/students?profileUserId=\"+encodeURIComponent(userId));\n   setProfile(result.profile);\n  }catch(e){setError(e instanceof Error?e.message:\"تعذر فتح ملف الطالب.\");}\n  finally{setProfileBusy(false)}\n }\n\n async function openAttempt(assignmentId:string,studentId:string,attemptNumber:number){\n  setReviewBusy(true);setError(\"\");\n  try{\n   const params=new URLSearchParams({assignmentId,studentId,attemptNumber:String(attemptNumber)});\n   const result=await teacherApi<{ok:true}&AttemptReview>(\"/api/assignment-review?\"+params.toString());\n   setReview(result);\n  }catch(e){setError(e instanceof Error?e.message:\"تعذر فتح تفاصيل المحاولة.\");}\n  finally{setReviewBusy(false)}\n }\n\n function exportCsv(){\n  if(!data)return;\n  const rows:string[][]=[\n   [\"ExamBank - Teacher Analytics\"],\n   [\"النطاق\",data.scope.className],\n   [\"تاريخ التقرير\",fmtDate(data.generatedAt)],\n   [],\n   [\"المؤشر\",\"القيمة\"],\n   [\"الطلاب\",String(data.kpis.activeStudents)],\n   [\"متوسط العلامات\",fmtPct(data.kpis.average)],\n   [\"نسبة التسليم\",fmtPct(data.kpis.completionRate)],\n   [\"يحتاجون متابعة\",String(data.kpis.followUpStudents)],\n   [\"واجبات منشورة\",String(data.kpis.publishedAssignments)],\n   [\"تسليمات ناقصة\",String(data.kpis.missingSubmissions)],\n   [],\n   [\"الواجب\",\"الصف\",\"المتوسط\",\"التسليم\",\"لم يسلم\",\"مراجعة\"],\n   ...data.assignmentTrend.map(item=>[item.title,item.className,fmtPct(item.average),fmtPct(item.completionRate),String(item.missing),String(item.pendingReview)]),\n   [],\n   [\"طلاب يحتاجون متابعة\",\"الصف\",\"المعدل\",\"ناقص\",\"الاتجاه\",\"السبب\"],\n   ...data.followUp.map(item=>[item.displayName,item.className,fmtPct(item.average),String(item.missing),trendText(item.trendDelta),item.reasons.join(\"، \")]),\n   [],\n   [\"الموضوع\",\"المتوسط\",\"إجابات مصححة\"],\n   ...data.topicAnalytics.map(item=>[item.topic,fmtPct(item.average),String(item.gradedQuestions)])\n  ];\n  const content=\"\\ufeff\"+rows.map(row=>row.map(csvCell).join(\",\")).join(\"\\r\\n\");\n  const blob=new Blob([content],{type:\"text/csv;charset=utf-8\"});\n  const url=URL.createObjectURL(blob),a=document.createElement(\"a\");\n  a.href=url;a.download=\"ExamBank-Teacher-Analytics.csv\";a.click();URL.revokeObjectURL(url);\n }\n\n if(!data&&loading)return <div className=\"analytics-loading\">⏳ جارٍ بناء لوحة التحليل...</div>;\n if(!data)return <div className=\"platform-error\">{error||\"لا توجد بيانات لعرضها.\"}</div>;\n\n const k=data.kpis;\n const selectedClass=data.classes.find(item=>item.classId===classId);\n\n return <div className=\"analytics-dashboard\" dir=\"rtl\">\n  <section className=\"analytics-hero\">\n   <div><span className=\"platform-eyebrow\">Professional Teacher Analytics</span><h2>لوحة المتابعة والتحليل</h2><p>نظرة شاملة على أداء الطلاب، التسليمات، الاتجاهات والموضوعات التي تحتاج تدخلًا.</p></div>\n   <div className=\"analytics-hero-actions\"><button onClick={()=>void loadDashboard()} disabled={loading}>↻ تحديث</button><button onClick={exportCsv}>⬇ Excel / CSV</button><button onClick={()=>window.print()}>🖨 طباعة / PDF</button></div>\n  </section>\n\n  <section className=\"analytics-filter-bar\">\n   <label>الصف<select value={classId} onChange={(e:{target:{value:string}})=>setClassId(e.target.value)}><option value=\"\">كل الصفوف</option>{data.classes.filter(item=>item.active).map(item=><option key={item.classId} value={item.classId}>{item.name} · {item.grade||\"—\"}</option>)}</select></label>\n   <label>الفترة<select value={range} onChange={(e:{target:{value:string}})=>setRange(e.target.value as RangeKey)}><option value=\"all\">كل الفترة</option><option value=\"30\">آخر 30 يومًا</option><option value=\"90\">آخر 90 يومًا</option><option value=\"365\">آخر سنة</option></select></label>\n   <div className=\"analytics-scope\"><strong>{selectedClass?.name||\"كل الصفوف\"}</strong><span>آخر تحديث: {fmtDate(data.generatedAt)}</span></div>\n  </section>\n\n  {error&&<div className=\"platform-error\">{error}</div>}\n\n  <section className=\"analytics-kpi-grid\">\n   <article className=\"analytics-kpi\"><span>الطلاب الفعّالون</span><strong>{k.activeStudents}</strong><small>{classId?\"في الصف المختار\":k.activeClasses+\" صفوف فعّالة\"}</small></article>\n   <article className=\"analytics-kpi\"><span>متوسط العلامات</span><strong>{fmtPct(k.average)}</strong><small>{k.highest===null?\"لا توجد نتائج\":\"أعلى \"+fmtPct(k.highest)+\" · أدنى \"+fmtPct(k.lowest)}</small></article>\n   <article className=\"analytics-kpi\"><span>نسبة التسليم</span><strong>{fmtPct(k.completionRate)}</strong><small>{k.submissions} من {k.expectedSubmissions} حالة متوقعة</small></article>\n   <article className=\"analytics-kpi attention\"><span>يحتاجون متابعة</span><strong>{k.followUpStudents}</strong><small>{k.neverLogged} لم يسجلوا الدخول</small></article>\n   <article className=\"analytics-kpi\"><span>واجبات منشورة</span><strong>{k.publishedAssignments}</strong><small>{k.pendingReview} تحتاج مراجعة</small></article>\n   <article className={`analytics-kpi ${k.performanceChange<0?\"negative\":\"positive\"}`}><span>اتجاه الأداء</span><strong>{trendIcon(k.performanceChange)} {Math.abs(k.performanceChange).toFixed(1)}%</strong><small>{trendText(k.performanceChange)} مقارنة بالواجبات السابقة</small></article>\n  </section>\n\n  <section className=\"analytics-main-grid\">\n   <article className=\"analytics-card analytics-wide\"><div className=\"analytics-card-head\"><div><span className=\"platform-eyebrow\">Performance Trend</span><h3>تطور متوسط الأداء</h3></div><span className=\"analytics-chip\">آخر {data.assignmentTrend.length} واجبات</span></div><LineChart items={data.assignmentTrend}/></article>\n   <article className=\"analytics-card\"><div className=\"analytics-card-head\"><div><span className=\"platform-eyebrow\">Submission Status</span><h3>حالة التسليم</h3></div></div><DonutChart submitted={data.submissionStatus.submitted} missing={data.submissionStatus.missing} pendingReview={data.submissionStatus.pendingReview}/></article>\n  </section>\n\n  <section className=\"analytics-main-grid\">\n   <article className=\"analytics-card\"><div className=\"analytics-card-head\"><div><span className=\"platform-eyebrow\">Grade Distribution</span><h3>توزيع العلامات</h3></div></div><div className=\"analytics-bars\">{data.gradeDistribution.map(item=><div className=\"analytics-bar-row\" key={item.label}><span>{item.label}</span><div><i style={{width:(item.count/maxDistribution*100)+\"%\"}}/></div><b>{item.count}</b></div>)}</div></article>\n   <article className=\"analytics-card\"><div className=\"analytics-card-head\"><div><span className=\"platform-eyebrow\">Class Comparison</span><h3>مقارنة الصفوف</h3></div></div><div className=\"analytics-bars\">{data.classComparison.map(item=><button className=\"analytics-bar-row analytics-bar-button\" key={item.classId} onClick={()=>setClassId(item.classId)}><span>{item.name}</span><div><i style={{width:(Number(item.average||0)/maxClassAverage*100)+\"%\"}}/></div><b>{fmtPct(item.average)}</b></button>)}{!data.classComparison.length&&<div className=\"analytics-empty-chart\">لا توجد بيانات صفوف بعد.</div>}</div></article>\n  </section>\n\n  <section className=\"analytics-main-grid\">\n   <article className=\"analytics-card\"><div className=\"analytics-card-head\"><div><span className=\"platform-eyebrow\">Topic Analytics</span><h3>الأداء حسب الموضوع</h3></div><span className=\"analytics-chip\">الأضعف أولًا</span></div><div className=\"analytics-topic-list\">{data.topicAnalytics.map(item=><div key={item.topic}><div><strong>{item.topic}</strong><span>{fmtPct(item.average)} · {item.gradedQuestions} إجابة مصححة</span></div><div className=\"analytics-topic-track\"><i className={Number(item.average||0)<60?\"weak\":Number(item.average||0)>=80?\"strong\":\"\"} style={{width:clampPct(item.average)+\"%\"}}/></div></div>)}{!data.topicAnalytics.length&&<div className=\"analytics-empty-chart\">ستظهر تحليلات الموضوعات بعد وجود إجابات مصححة.</div>}</div></article>\n   <article className=\"analytics-card\"><div className=\"analytics-card-head\"><div><span className=\"platform-eyebrow\">Smart Insights</span><h3>مؤشرات ذكية للمعلم</h3></div></div><div className=\"analytics-insights\">{data.insights.map((item,index)=><article key={index} className={\"analytics-insight \"+item.tone}><div className=\"analytics-insight-icon\">{item.tone===\"success\"?\"✓\":item.tone===\"warning\"?\"!\":\"i\"}</div><div><strong>{item.title}</strong><p>{item.text}</p></div></article>)}</div></article>\n  </section>\n\n  <section className=\"analytics-main-grid\">\n   <article className=\"analytics-card analytics-wide\"><div className=\"analytics-card-head\"><div><span className=\"platform-eyebrow\">Follow-up Center</span><h3>طلاب يحتاجون متابعة</h3></div><span className=\"analytics-chip warning\">{data.followUp.length}</span></div><div className=\"students-table-wrap\"><table className=\"students-table analytics-table\"><thead><tr><th>الطالب</th><th>الصف</th><th>المعدل</th><th>غير مسلّم</th><th>الاتجاه</th><th>السبب</th><th></th></tr></thead><tbody>{data.followUp.map(item=><tr key={item.userId}><td><button className=\"analytics-link\" onClick={()=>void openProfile(item.userId)}>{item.displayName}</button><small>{maskIdentity(item.identityNumber)}</small></td><td>{item.className}</td><td>{fmtPct(item.average)}</td><td>{item.missing}</td><td><span className={\"analytics-trend-badge \"+item.trend}>{trendIcon(item.trendDelta)} {trendText(item.trendDelta)} {item.trendDelta?Math.abs(item.trendDelta)+\"%\":\"\"}</span></td><td>{item.reasons.join(\"، \")}</td><td><span className={\"analytics-risk \"+item.severity}>{item.severity===\"high\"?\"عاجل\":\"متابعة\"}</span></td></tr>)}{!data.followUp.length&&<tr><td colSpan={7}>لا توجد حالات متابعة بارزة ضمن النطاق الحالي.</td></tr>}</tbody></table></div></article>\n   <article className=\"analytics-card\"><div className=\"analytics-card-head\"><div><span className=\"platform-eyebrow\">Improvement</span><h3>أفضل تحسن</h3></div></div><div className=\"analytics-improvers\">{data.topImprovers.map((item,index)=><button key={item.userId} onClick={()=>void openProfile(item.userId)}><span className=\"analytics-rank\">{index+1}</span><div><strong>{item.displayName}</strong><small>{item.className}</small></div><b>↑ {item.trendDelta}%</b></button>)}{!data.topImprovers.length&&<div className=\"analytics-empty-chart\">نحتاج نتائج متتابعة أكثر لقياس التحسن.</div>}</div></article>\n  </section>\n\n  <section className=\"analytics-card analytics-assignment-card\"><div className=\"analytics-card-head\"><div><span className=\"platform-eyebrow\">Assignments</span><h3>متابعة الواجبات</h3></div><span className=\"analytics-chip\">اضغط على واجب للتفاصيل</span></div><div className=\"students-table-wrap\"><table className=\"students-table analytics-table\"><thead><tr><th>الواجب</th><th>الصف</th><th>المتوسط</th><th>التسليم</th><th>غير مسلّم</th><th>مراجعة</th><th>الموعد</th></tr></thead><tbody>{[...data.assignmentTrend].reverse().map(item=><tr key={item.assignmentId} className=\"analytics-click-row\" onClick={()=>void openAssignment(item)}><td><strong>{item.title}</strong></td><td>{item.className}</td><td>{fmtPct(item.average)}</td><td>{fmtPct(item.completionRate)}</td><td>{item.missing}</td><td>{item.pendingReview}</td><td>{item.dueAt?fmtDate(item.dueAt):\"—\"}</td></tr>)}{!data.assignmentTrend.length&&<tr><td colSpan={7}>لا توجد واجبات منشورة ضمن النطاق الحالي.</td></tr>}</tbody></table></div></section>\n\n  {assignmentBusy&&<div className=\"analytics-loading\">جارٍ تحميل تفاصيل الواجب...</div>}\n  {assignmentResults&&<section className=\"analytics-drill-card\"><div className=\"analytics-card-head\"><div><span className=\"platform-eyebrow\">Drill Down · Assignment</span><h3>{assignmentResults.assignment.title}</h3><p>من الواجب ← الطالب ← المحاولة ← السؤال</p></div><button onClick={()=>{setAssignmentResults(null);setReview(null)}}>إغلاق</button></div><div className=\"analytics-mini-kpis\"><span>المتوسط <b>{fmtPct(assignmentResults.stats.average)}</b></span><span>سلّموا <b>{assignmentResults.stats.submitted}/{assignmentResults.stats.students}</b></span><span>مراجعة <b>{assignmentResults.stats.pendingReview}</b></span><span>أعلى <b>{fmtPct(assignmentResults.stats.highest)}</b></span></div><div className=\"students-table-wrap\"><table className=\"students-table analytics-table\"><thead><tr><th>الطالب</th><th>المحاولات</th><th>آخر علامة</th><th>الحالة</th><th>فتح محاولة</th></tr></thead><tbody>{assignmentResults.students.map(student=><tr key={student.studentId}><td><button className=\"analytics-link\" onClick={()=>void openProfile(student.studentId)}>{student.studentName}</button></td><td>{student.attemptsUsed}/{student.allowedAttempts}</td><td>{student.latestResult?fmtPct(student.latestResult.percentage):\"—\"}</td><td>{!student.latestResult?\"لم يسلّم\":student.latestResult.finalized?\"مصحح\":\"يحتاج مراجعة\"}</td><td><div className=\"analytics-attempt-buttons\">{student.attempts.map(attempt=><button key={attempt.attemptNumber} onClick={()=>void openAttempt(assignmentResults.assignment.assignmentId,student.studentId,attempt.attemptNumber)}>#{attempt.attemptNumber} · {fmtPct(attempt.percentage)}</button>)}</div></td></tr>)}</tbody></table></div></section>}\n\n  {profileBusy&&<div className=\"analytics-loading\">جارٍ فتح ملف الطالب...</div>}\n  {profile&&<section className=\"analytics-drill-card\"><div className=\"analytics-card-head\"><div><span className=\"platform-eyebrow\">Drill Down · Student</span><h3>{profile.student.displayName}</h3><p>{profile.classroom?.name||\"—\"} · {maskIdentity(profile.student.identityNumber)}</p></div><button onClick={()=>setProfile(null)}>إغلاق</button></div><div className=\"analytics-mini-kpis\"><span>المعدل <b>{fmtPct(profile.stats.average)}</b></span><span>مكتملة <b>{profile.stats.completed}/{profile.stats.assigned}</b></span><span>ناقصة <b>{profile.stats.pending}</b></span><span>آخر دخول <b>{profile.stats.lastLoginAt?fmtDate(profile.stats.lastLoginAt):\"لم يدخل\"}</b></span></div><div className=\"students-table-wrap\"><table className=\"students-table analytics-table\"><thead><tr><th>الواجب</th><th>المحاولات</th><th>العلامة</th><th>النسبة</th><th>الحالة</th></tr></thead><tbody>{profile.assignments.map(item=><tr key={item.assignmentId}><td>{item.title}</td><td>{item.attemptsUsed}</td><td>{item.latestScore===null?\"—\":item.latestScore+\"/\"+item.totalMarks}</td><td>{fmtPct(item.latestPercentage)}</td><td>{item.latestScore===null?\"لم يسلّم\":item.finalized?\"مصحح\":\"مراجعة\"}</td></tr>)}</tbody></table></div></section>}\n\n  {reviewBusy&&<div className=\"analytics-loading\">جارٍ فتح تفاصيل المحاولة...</div>}\n  {review&&<section className=\"analytics-drill-card\"><div className=\"analytics-card-head\"><div><span className=\"platform-eyebrow\">Drill Down · Attempt · Questions</span><h3>{review.student.studentName} · المحاولة #{review.attempt.attemptNumber}</h3><p>{review.assignment.title} · {fmtPct(review.attempt.percentage)} · {review.attempt.finalized?\"مصححة بالكامل\":\"تحتاج مراجعة\"}</p></div><button onClick={()=>setReview(null)}>إغلاق</button></div><div className=\"analytics-attempt-buttons analytics-attempt-switcher\">{review.attempts.map(attempt=><button className={attempt.attemptNumber===review.attempt.attemptNumber?\"active\":\"\"} key={attempt.attemptNumber} onClick={()=>void openAttempt(review.assignment.assignmentId,review.student.studentId,attempt.attemptNumber)}>محاولة #{attempt.attemptNumber} · {fmtPct(attempt.percentage)}</button>)}</div><div className=\"students-table-wrap\"><table className=\"students-table analytics-table\"><thead><tr><th>#</th><th>السؤال</th><th>النوع</th><th>العلامة</th><th>الحالة</th></tr></thead><tbody>{review.questions.map(question=>{const score=question.manualScore??question.autoGrade?.score??0;const max=question.autoGrade?.maxMarks??question.marks;const pending=question.autoGrade?.manualReview===true&&question.autoGrade?.reviewed!==true&&question.manualScore===null;return <tr key={question.questionId}><td>{question.questionNumber}</td><td className=\"analytics-question-text\">{question.text}</td><td>{question.type||\"—\"}</td><td>{score}/{max}</td><td>{pending?<span className=\"analytics-risk high\">مراجعة</span>:<span className=\"status-active\">مصحح</span>}</td></tr>})}</tbody></table></div>{review.attempt.teacherFeedback&&<div className=\"analytics-feedback\"><strong>ملاحظة المعلم:</strong> {review.attempt.teacherFeedback}</div>}</section>}\n </div>;\n}\n\nexport default TeacherDashboard;\n";
const dashboardCss = "/* ============================================================\n   ExamBank 2.0I - Professional Teacher Analytics Dashboard\n   ============================================================ */\n\n.teacher-workspace-nav {\n  display: flex;\n  align-items: center;\n  gap: 8px;\n  margin-bottom: 16px;\n  padding: 7px;\n  border: 1px solid #dbe3ee;\n  border-radius: 16px;\n  background: rgba(255,255,255,.94);\n  box-shadow: 0 8px 24px rgba(15,23,42,.06);\n  position: sticky;\n  top: 8px;\n  z-index: 20;\n  backdrop-filter: blur(12px);\n}\n\n.teacher-workspace-nav button {\n  flex: 1;\n  border: 0;\n  border-radius: 11px;\n  padding: 11px 12px;\n  background: transparent;\n  color: #475569;\n  font-weight: 900;\n  cursor: pointer;\n}\n\n.teacher-workspace-nav button:hover {\n  background: #f8fafc;\n  color: #0f172a;\n}\n\n.teacher-workspace-nav button.active {\n  background: #0f172a;\n  color: #fff;\n  box-shadow: 0 7px 18px rgba(15,23,42,.16);\n}\n\n.teacher-assignment-heading {\n  margin-bottom: 14px;\n  padding: 18px 20px;\n  border-radius: 18px;\n  border: 1px solid #dbe3ee;\n  background: linear-gradient(135deg,#ffffff,#f8fbff);\n}\n\n.teacher-assignment-heading h2 {\n  margin: 4px 0 5px;\n  color: #0f172a;\n}\n\n.teacher-assignment-heading p {\n  margin: 0;\n  color: #64748b;\n}\n\n.analytics-dashboard {\n  display: flex;\n  flex-direction: column;\n  gap: 16px;\n}\n\n.analytics-hero {\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  gap: 18px;\n  padding: 24px;\n  border-radius: 22px;\n  background: linear-gradient(135deg,#0b1220 0%,#12223f 52%,#163b74 100%);\n  color: #fff;\n  box-shadow: 0 22px 48px rgba(15,23,42,.16);\n  overflow: hidden;\n  position: relative;\n}\n\n.analytics-hero::after {\n  content: \"\";\n  position: absolute;\n  width: 240px;\n  height: 240px;\n  border-radius: 50%;\n  left: -60px;\n  top: -120px;\n  background: rgba(255,255,255,.06);\n}\n\n.analytics-hero h2 {\n  margin: 5px 0 7px;\n  font-size: clamp(24px,3vw,34px);\n}\n\n.analytics-hero p {\n  margin: 0;\n  color: #dbeafe;\n  line-height: 1.7;\n}\n\n.analytics-hero-actions {\n  display: flex;\n  gap: 8px;\n  flex-wrap: wrap;\n  position: relative;\n  z-index: 1;\n}\n\n.analytics-hero-actions button,\n.analytics-card-head > button,\n.analytics-drill-card > .analytics-card-head button {\n  border: 1px solid rgba(255,255,255,.25);\n  background: rgba(255,255,255,.1);\n  color: inherit;\n  border-radius: 10px;\n  padding: 9px 11px;\n  font-weight: 800;\n  cursor: pointer;\n}\n\n.analytics-filter-bar {\n  display: grid;\n  grid-template-columns: minmax(180px,240px) minmax(160px,210px) 1fr;\n  gap: 10px;\n  align-items: end;\n  padding: 13px;\n  border: 1px solid #dbe3ee;\n  background: #fff;\n  border-radius: 16px;\n  box-shadow: 0 7px 22px rgba(15,23,42,.04);\n}\n\n.analytics-filter-bar label {\n  display: flex;\n  flex-direction: column;\n  gap: 5px;\n  color: #64748b;\n  font-size: 11px;\n  font-weight: 900;\n}\n\n.analytics-filter-bar select {\n  width: 100%;\n  border: 1px solid #cbd5e1;\n  border-radius: 10px;\n  padding: 10px 11px;\n  background: #fff;\n  color: #0f172a;\n  font: inherit;\n}\n\n.analytics-scope {\n  display: flex;\n  flex-direction: column;\n  align-items: flex-end;\n  gap: 3px;\n  padding: 3px 5px 3px 0;\n}\n\n.analytics-scope strong { color: #0f172a; }\n.analytics-scope span { color: #94a3b8; font-size: 11px; }\n\n.analytics-kpi-grid {\n  display: grid;\n  grid-template-columns: repeat(6,minmax(135px,1fr));\n  gap: 10px;\n}\n\n.analytics-kpi {\n  padding: 16px;\n  border: 1px solid #dbe3ee;\n  border-radius: 16px;\n  background: #fff;\n  box-shadow: 0 8px 24px rgba(15,23,42,.045);\n  min-width: 0;\n}\n\n.analytics-kpi > span {\n  display: block;\n  color: #64748b;\n  font-size: 11px;\n  font-weight: 900;\n}\n\n.analytics-kpi > strong {\n  display: block;\n  margin: 5px 0 3px;\n  color: #0f172a;\n  font-size: 26px;\n  letter-spacing: -.02em;\n}\n\n.analytics-kpi > small {\n  color: #94a3b8;\n  line-height: 1.45;\n}\n\n.analytics-kpi.attention { border-color: #fed7aa; background: linear-gradient(180deg,#fff,#fffaf3); }\n.analytics-kpi.positive > strong { color: #15803d; }\n.analytics-kpi.negative > strong { color: #b42318; }\n\n.analytics-main-grid {\n  display: grid;\n  grid-template-columns: minmax(0,1.55fr) minmax(300px,.8fr);\n  gap: 14px;\n}\n\n.analytics-card,\n.analytics-drill-card {\n  border: 1px solid #dbe3ee;\n  border-radius: 18px;\n  background: #fff;\n  padding: 17px;\n  box-shadow: 0 9px 28px rgba(15,23,42,.045);\n  min-width: 0;\n}\n\n.analytics-wide { min-width: 0; }\n\n.analytics-card-head {\n  display: flex;\n  align-items: flex-start;\n  justify-content: space-between;\n  gap: 12px;\n  margin-bottom: 12px;\n}\n\n.analytics-card-head h3 {\n  margin: 3px 0 0;\n  color: #0f172a;\n  font-size: 17px;\n}\n\n.analytics-card-head p {\n  margin: 5px 0 0;\n  color: #64748b;\n  font-size: 12px;\n}\n\n.analytics-chip {\n  display: inline-flex;\n  align-items: center;\n  justify-content: center;\n  min-height: 27px;\n  padding: 0 9px;\n  border-radius: 999px;\n  background: #eff6ff;\n  color: #1d4ed8;\n  font-size: 10px;\n  font-weight: 900;\n  white-space: nowrap;\n}\n\n.analytics-chip.warning { background: #fff7ed; color: #c2410c; }\n\n.analytics-line-wrap {\n  width: 100%;\n  overflow-x: auto;\n}\n\n.analytics-line-wrap svg {\n  display: block;\n  width: 100%;\n  min-width: 620px;\n  height: auto;\n}\n\n.analytics-grid-line { stroke: #e8eef5; stroke-width: 1; }\n.analytics-axis-text,.analytics-axis-label { fill: #94a3b8; font-size: 10px; }\n.analytics-point-value { fill: #334155; font-size: 10px; font-weight: 800; }\n.analytics-trend-line { fill: none; stroke: #2563eb; stroke-width: 3; stroke-linecap: round; stroke-linejoin: round; }\n.analytics-trend-area { fill: rgba(37,99,235,.08); stroke: none; }\n.analytics-trend-dot { fill: #fff; stroke: #2563eb; stroke-width: 3; }\n\n.analytics-empty-chart,\n.analytics-loading {\n  min-height: 120px;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  color: #94a3b8;\n  text-align: center;\n  padding: 20px;\n}\n\n.analytics-donut-layout {\n  min-height: 250px;\n  display: grid;\n  grid-template-columns: 150px 1fr;\n  gap: 16px;\n  align-items: center;\n}\n\n.analytics-donut {\n  width: 150px;\n  height: 150px;\n  transform: rotate(-90deg);\n}\n\n.analytics-donut circle {\n  fill: none;\n  stroke-width: 13;\n}\n\n.donut-track { stroke: #eef2f7; }\n.donut-submitted { stroke: #2563eb; }\n.donut-missing { stroke: #f59e0b; }\n.analytics-donut text { transform: rotate(90deg); transform-origin: 60px 60px; fill: #0f172a; }\n.analytics-donut .donut-main { font-size: 19px; font-weight: 900; }\n.analytics-donut .donut-sub { font-size: 8px; fill: #64748b; }\n\n.analytics-legend {\n  display: flex;\n  flex-direction: column;\n  gap: 9px;\n  color: #475569;\n  font-size: 12px;\n}\n\n.analytics-legend span { display: flex; align-items: center; gap: 7px; }\n.analytics-legend b { margin-right: auto; color: #0f172a; }\n.legend-dot { width: 9px; height: 9px; border-radius: 50%; display: inline-block; }\n.legend-dot.submitted { background: #2563eb; }\n.legend-dot.missing { background: #f59e0b; }\n.legend-dot.review { background: #8b5cf6; }\n\n.analytics-bars,\n.analytics-topic-list,\n.analytics-insights,\n.analytics-improvers {\n  display: flex;\n  flex-direction: column;\n  gap: 9px;\n}\n\n.analytics-bar-row {\n  display: grid;\n  grid-template-columns: minmax(70px,110px) 1fr minmax(40px,70px);\n  align-items: center;\n  gap: 9px;\n  color: #475569;\n  font-size: 11px;\n}\n\n.analytics-bar-row > div {\n  height: 8px;\n  border-radius: 999px;\n  background: #eef2f7;\n  overflow: hidden;\n}\n\n.analytics-bar-row i {\n  display: block;\n  height: 100%;\n  border-radius: inherit;\n  background: linear-gradient(90deg,#2563eb,#60a5fa);\n}\n\n.analytics-bar-row b { color: #0f172a; text-align: left; }\n\n.analytics-bar-button {\n  width: 100%;\n  border: 0;\n  padding: 4px 0;\n  background: transparent;\n  cursor: pointer;\n  text-align: right;\n}\n\n.analytics-bar-button:hover span { color: #1d4ed8; }\n\n.analytics-topic-list > div {\n  padding: 7px 0;\n  border-bottom: 1px solid #f1f5f9;\n}\n\n.analytics-topic-list > div:last-child { border-bottom: 0; }\n.analytics-topic-list > div > div:first-child { display: flex; justify-content: space-between; gap: 12px; margin-bottom: 6px; }\n.analytics-topic-list strong { color: #334155; font-size: 12px; }\n.analytics-topic-list span { color: #94a3b8; font-size: 10px; text-align: left; }\n.analytics-topic-track { height: 7px; background: #eef2f7; border-radius: 999px; overflow: hidden; }\n.analytics-topic-track i { display: block; height: 100%; background: #3b82f6; border-radius: inherit; }\n.analytics-topic-track i.weak { background: #ef4444; }\n.analytics-topic-track i.strong { background: #22c55e; }\n\n.analytics-insight {\n  display: grid;\n  grid-template-columns: 30px 1fr;\n  gap: 10px;\n  padding: 10px;\n  border-radius: 12px;\n  border: 1px solid #e2e8f0;\n  background: #f8fafc;\n}\n\n.analytics-insight.success { background: #f0fdf4; border-color: #bbf7d0; }\n.analytics-insight.warning { background: #fff7ed; border-color: #fed7aa; }\n.analytics-insight.info { background: #eff6ff; border-color: #bfdbfe; }\n.analytics-insight-icon { width: 28px; height: 28px; display: grid; place-items: center; border-radius: 50%; background: #fff; font-weight: 900; color: #334155; }\n.analytics-insight strong { color: #0f172a; font-size: 12px; }\n.analytics-insight p { margin: 3px 0 0; color: #64748b; font-size: 11px; line-height: 1.6; }\n\n.analytics-table td small { display: block; margin-top: 3px; color: #94a3b8; }\n.analytics-link { border: 0; background: transparent; color: #1d4ed8; font: inherit; font-weight: 900; padding: 0; cursor: pointer; text-align: right; }\n.analytics-click-row { cursor: pointer; }\n.analytics-click-row:hover { background: #f8fbff; }\n\n.analytics-trend-badge,\n.analytics-risk {\n  display: inline-flex;\n  align-items: center;\n  border-radius: 999px;\n  padding: 4px 7px;\n  font-size: 10px;\n  font-weight: 900;\n  white-space: nowrap;\n}\n\n.analytics-trend-badge.improving { background: #dcfce7; color: #166534; }\n.analytics-trend-badge.declining { background: #fee2e2; color: #991b1b; }\n.analytics-trend-badge.stable { background: #f1f5f9; color: #475569; }\n.analytics-risk.high { background: #fee2e2; color: #991b1b; }\n.analytics-risk.medium { background: #fef3c7; color: #92400e; }\n.analytics-risk.low { background: #f1f5f9; color: #475569; }\n\n.analytics-improvers button {\n  display: grid;\n  grid-template-columns: 30px 1fr auto;\n  align-items: center;\n  gap: 9px;\n  border: 1px solid #e2e8f0;\n  background: #fff;\n  border-radius: 11px;\n  padding: 9px;\n  cursor: pointer;\n  text-align: right;\n}\n\n.analytics-improvers button:hover { border-color: #93c5fd; background: #f8fbff; }\n.analytics-rank { width: 27px; height: 27px; display: grid; place-items: center; border-radius: 9px; background: #eff6ff; color: #1d4ed8; font-weight: 900; }\n.analytics-improvers strong { display: block; color: #0f172a; font-size: 11px; }\n.analytics-improvers small { color: #94a3b8; }\n.analytics-improvers b { color: #15803d; font-size: 11px; }\n\n.analytics-assignment-card { width: 100%; box-sizing: border-box; }\n\n.analytics-drill-card {\n  border-color: #bfdbfe;\n  background: linear-gradient(180deg,#ffffff,#f8fbff);\n  box-shadow: 0 14px 34px rgba(37,99,235,.08);\n}\n\n.analytics-drill-card .analytics-card-head > button {\n  color: #334155;\n  background: #fff;\n  border-color: #cbd5e1;\n}\n\n.analytics-mini-kpis {\n  display: flex;\n  gap: 8px;\n  flex-wrap: wrap;\n  margin-bottom: 10px;\n}\n\n.analytics-mini-kpis span {\n  display: inline-flex;\n  align-items: center;\n  gap: 5px;\n  padding: 7px 9px;\n  background: #f8fafc;\n  border: 1px solid #e2e8f0;\n  border-radius: 9px;\n  color: #64748b;\n  font-size: 10px;\n}\n\n.analytics-mini-kpis b { color: #0f172a; }\n\n.analytics-attempt-buttons {\n  display: flex;\n  flex-wrap: wrap;\n  gap: 5px;\n}\n\n.analytics-attempt-buttons button {\n  border: 1px solid #cbd5e1;\n  border-radius: 8px;\n  background: #fff;\n  padding: 5px 7px;\n  color: #334155;\n  font-size: 10px;\n  cursor: pointer;\n}\n\n.analytics-attempt-buttons button.active {\n  border-color: #2563eb;\n  background: #eff6ff;\n  color: #1d4ed8;\n  font-weight: 900;\n}\n\n.analytics-attempt-switcher { margin-bottom: 10px; }\n.analytics-question-text { min-width: 300px; max-width: 560px; white-space: normal; line-height: 1.55; }\n.analytics-feedback { margin-top: 10px; padding: 10px 12px; border-radius: 10px; background: #fffbeb; color: #92400e; font-size: 11px; }\n\n@media (max-width: 1100px) {\n  .analytics-kpi-grid { grid-template-columns: repeat(3,minmax(150px,1fr)); }\n  .analytics-main-grid { grid-template-columns: 1fr; }\n}\n\n@media (max-width: 720px) {\n  .teacher-workspace-nav { position: static; display: grid; grid-template-columns: 1fr; }\n  .analytics-hero { align-items: flex-start; flex-direction: column; }\n  .analytics-filter-bar { grid-template-columns: 1fr; }\n  .analytics-scope { align-items: flex-start; }\n  .analytics-kpi-grid { grid-template-columns: repeat(2,minmax(130px,1fr)); }\n  .analytics-donut-layout { grid-template-columns: 1fr; justify-items: center; }\n  .analytics-legend { width: 100%; }\n}\n\n@media (max-width: 470px) {\n  .analytics-kpi-grid { grid-template-columns: 1fr; }\n  .analytics-card,.analytics-drill-card { padding: 13px; }\n}\n\n@media print {\n  .teacher-workspace-nav,\n  .analytics-hero-actions,\n  .analytics-filter-bar select,\n  .analytics-drill-card,\n  .student-row-actions { display: none !important; }\n  .teacher-platform { background: #fff !important; padding: 0 !important; }\n  .teacher-platform-inner { width: 100% !important; }\n  .analytics-card,.analytics-kpi,.analytics-hero { box-shadow: none !important; break-inside: avoid; }\n  .analytics-hero { background: #fff !important; color: #000 !important; border: 1px solid #ddd; }\n  .analytics-hero p { color: #444 !important; }\n}\n";

fs.writeFileSync(files.analytics, analyticsBackend, "utf8");
fs.writeFileSync(files.dashboard, dashboardFrontend, "utf8");

if (!teacher.includes('import TeacherDashboard from "./TeacherDashboard";')) {
  const importMarker = 'import AssignmentsPanel from "./AssignmentsPanel";';
  if (!teacher.includes(importMarker)) fail("لم أجد import الخاص بـ AssignmentsPanel.");
  teacher = teacher.replace(importMarker, importMarker + '\nimport TeacherDashboard from "./TeacherDashboard";');
}

if (!teacher.includes("workspaceTab")) {
  const stateMarker = ' const [profileBusy,setProfileBusy]=useState(false);';
  if (!teacher.includes(stateMarker)) fail("لم أجد موضع إضافة حالة التنقل في TeacherPlatform.tsx");
  teacher = teacher.replace(
    stateMarker,
    stateMarker + '\n const [workspaceTab,setWorkspaceTab]=useState<"dashboard"|"students"|"assignments">("dashboard");'
  );
}

// Remove the old always-visible assignments section. It will live in its own professional tab.
const oldAssignmentsAtBottom = '\n  <AssignmentsPanel token={token} classes={classes} currentExam={currentExam}/>';
if (teacher.includes(oldAssignmentsAtBottom)) teacher = teacher.replace(oldAssignmentsAtBottom, "");

if (!teacher.includes('className="teacher-workspace-nav"')) {
  const selectedCountMarker = ' const selectedCount=selectedIds.length;';
  if (!teacher.includes(selectedCountMarker)) fail("لم أجد موضع إضافة تنقل منصة المعلم.");
  const navBlock = ` const workspaceNav=<nav className="teacher-workspace-nav" aria-label="أقسام منصة المعلم">
  <button className={workspaceTab==="dashboard"?"active":""} onClick={()=>setWorkspaceTab("dashboard")}>📊 لوحة المتابعة</button>
  <button className={workspaceTab==="students"?"active":""} onClick={()=>setWorkspaceTab("students")}>👥 الصفوف والطلاب</button>
  <button className={workspaceTab==="assignments"?"active":""} onClick={()=>setWorkspaceTab("assignments")}>📝 الواجبات</button>
 </nav>;

 if(workspaceTab==="dashboard")return <section className="teacher-platform" dir="rtl"><div className="teacher-platform-inner">{workspaceNav}<TeacherDashboard token={token}/></div></section>;
 if(workspaceTab==="assignments")return <section className="teacher-platform" dir="rtl"><div className="teacher-platform-inner">{workspaceNav}<section className="teacher-assignment-heading"><span className="platform-eyebrow">Assignments</span><h2>الواجبات والاختبارات المرسلة</h2><p>إنشاء الواجبات، متابعة التسليمات، التصحيح والنتائج.</p></section><AssignmentsPanel token={token} classes={classes} currentExam={currentExam}/></div></section>;

`;
  teacher = teacher.replace(selectedCountMarker, navBlock + selectedCountMarker);
}

const returnMarker = ' return <section className="teacher-platform" dir="rtl"><div className="teacher-platform-inner">';
if (!teacher.includes('{workspaceNav}\n  <section className="platform-hero">')) {
  if (!teacher.includes(returnMarker)) fail("لم أجد بداية واجهة إدارة الطلاب.");
  teacher = teacher.replace(returnMarker, returnMarker + '\n  {workspaceNav}', 1);
}

teacher = teacher.replace(/ExamBank 2\.0H/g, "ExamBank 2.0I");
fs.writeFileSync(files.teacher, teacher, "utf8");

let platformCss = fs.readFileSync(files.css, "utf8");
if (!platformCss.includes("ExamBank 2.0I - Professional Teacher Analytics Dashboard")) {
  platformCss = platformCss.replace(/\s*$/, "") + "\n\n" + dashboardCss.trim() + "\n";
  fs.writeFileSync(files.css, platformCss, "utf8");
}

console.log("Created api/src/functions/teacher-analytics.js");
console.log("Created src/TeacherDashboard.tsx");
console.log("Updated src/TeacherPlatform.tsx");
console.log("Updated src/platform.css");

console.log("\nChecking analytics backend syntax...");
execSync('node --check "api/src/functions/teacher-analytics.js"', { cwd: root, stdio: "inherit", shell: true });

console.log("\nRunning project build...\n");
execSync("npm run build", { cwd: root, stdio: "inherit", shell: true });

console.log("\nPhase 2.0I Professional Teacher Analytics installed successfully.");
